import { memo } from 'react';

import { useIntl } from 'react-intl';

import { DashText, SizableText, XStack } from '@onekeyhq/components';
import { ETranslations } from '@onekeyhq/shared/src/locale';

import { PORTFOLIO_TOKEN_COLUMN_WIDTH } from './portfolioColumnConstants';

const commonTextProps = {
  size: '$bodySmMedium',
  color: '$textSubdued',
} as const;

// The numeric columns share the row as equal flex thirds (explicit zero basis
// — Tamagui's `flex` keeps `flex-basis: auto`), so the first column hugs the
// left edge and the last one the right edge at any container width. The item
// rows use the same shares and the same 20px edge insets, keeping the two in
// column alignment.
function PortfolioHeaderNormalBase() {
  const intl = useIntl();

  return (
    <XStack
      py="$2"
      px="$5"
      alignItems="center"
      backgroundColor="$bgApp"
      gap="$6"
    >
      <SizableText {...commonTextProps} w={PORTFOLIO_TOKEN_COLUMN_WIDTH}>
        {intl.formatMessage({ id: ETranslations.perp_relay_token__title })}
      </SizableText>
      <SizableText
        {...commonTextProps}
        flex={1}
        flexBasis={0}
        minWidth={0}
        textAlign="right"
      >
        {intl.formatMessage({ id: ETranslations.global_balance })}
      </SizableText>
      <XStack flex={1} flexBasis={0} minWidth={0} justifyContent="flex-end">
        <DashText
          size="$bodySmMedium"
          color="$textSubdued"
          dashThickness={0.5}
          tooltip={intl.formatMessage({ id: ETranslations.marketdex_un_pnl })}
          tooltipTitle={intl.formatMessage({
            id: ETranslations.marketdex_pnl_cal,
          })}
        >
          {intl.formatMessage({
            id: ETranslations.marketdex_unrealized_pnl,
          })}
        </DashText>
      </XStack>
      <XStack flex={1} flexBasis={0} minWidth={0} justifyContent="flex-end">
        <DashText
          size="$bodySmMedium"
          color="$textSubdued"
          dashThickness={0.5}
          tooltip={intl.formatMessage({
            id: ETranslations.marketdex_total_pnl_desc,
          })}
          tooltipTitle={intl.formatMessage({
            id: ETranslations.marketdex_pnl_cal,
          })}
        >
          {intl.formatMessage({
            id: ETranslations.marketdex_total_pnl,
          })}
        </DashText>
      </XStack>
    </XStack>
  );
}

const PortfolioHeaderNormal = memo(PortfolioHeaderNormalBase);

export { PortfolioHeaderNormal };
